            InputStream tempOutputFileInputStream = TikaInputStream.get(tempOutputFile.toPath());
            IOUtils.copy(tempOutputFileInputStream, outputStream);
        }
    } finally {
        if (outputFromStdOut) {
            try {
                process.waitFor();
            } catch (InterruptedException ignore) {
            }
