            commandSegment = commandSegment.replace(ExternalParser.INPUT_FILE_TOKEN, tikaInputStream.getFile().toString());
            inputToStdIn = false;
        }
        if (commandSegment.contains(ExternalParser.OUTPUT_FILE_TOKEN)) {
            tempOutputFile = tmp.createTemporaryFile();
