 * @see Runtime#exec(String[])
 */
private String[] command = new String[]{ "sed", "-e", "$a\\\n" + METADATA_COMMAND_ARGUMENTS_SERIALIZED_TOKEN, ExternalParser.INPUT_FILE_TOKEN };

